# Now write a Node.js script to query the database and do the modification
node_script = '''
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get order #W4705780
const order = db.prepare("SELECT * FROM orders WHERE order_id = ?").get("#W4705780");
console.log("ORDER:", JSON.stringify(order, null, 2));

// Get order items
const items = db.prepare("SELECT * FROM order_items WHERE order_id = ?").all("#W4705780");
console.log("ITEMS:", JSON.stringify(items, null, 2));

// Find the joggers item
let joggerItem = null;
for (const item of items) {
    if (item.name && item.name.toLowerCase().includes('jogger')) {
        joggerItem = item;
    }
}
console.log("JOGGER_ITEM:", JSON.stringify(joggerItem, null, 2));

// Get variants for the joggers product
if (joggerItem) {
    const variants = db.prepare("SELECT * FROM rt_variants WHERE product_id = ?").all(joggerItem.product_id);
    console.log("VARIANTS:", JSON.stringify(variants, null, 2));

    // Find olive green M variant
    let targetVariant = null;
    for (const v of variants) {
        let opts = {};
        try { opts = JSON.parse(v.options || '{}'); } catch(e) {}
        const color = (opts.color || '').toLowerCase();
        const size = (opts.size || '').toUpperCase();
        if (color.includes('olive') && color.includes('green') && size === 'M') {
            targetVariant = v;
        }
    }
    console.log("TARGET_VARIANT:", JSON.stringify(targetVariant, null, 2));

    // Get user info
    const user = db.prepare("SELECT * FROM users WHERE user_id = ?").get(order.customer_id);
    console.log("USER:", JSON.stringify(user, null, 2));

    // Get payment methods
    const pms = db.prepare("SELECT * FROM rt_payment_methods WHERE user_id = ?").all(order.customer_id);
    console.log("PAYMENT_METHODS:", JSON.stringify(pms, null, 2));

    // Find credit card
    let ccPm = null;
    for (const pm of pms) {
        if (pm.source === 'credit_card') {
            ccPm = pm;
        }
    }
    console.log("CC_PM:", JSON.stringify(ccPm, null, 2));
}

db.close();
'''
w = await write_file("./query_db.js", node_script)
print(w)

